    (14, 35, "Ann iim Aa tig nn ele Lk bi Pn iNT YEH TITEETY ሁሁ ka iri መጠችበትም ሁሉ የረከፅ ነው።"),
    (14, 36, "ጸልጋዋንም (ምንጣፍን) የነክ ሁሉ ይጨልብፁቡ-ን ይጠብ ገላውንም በውኃ ይታጠብ ኣስከ ሠርኸም ርዀስ ነው።"),
