    (14, 47, "ክዝዳ፡ ጽዩ Zag [I ዘጐ› ደ ፫F።"),
    (14, 48, "ዘር ለሚፈስበትና ከሴትም ጋር ለሚተኛና ላደረ ስበት ሰው ሕኑ ሥራቱ ይህ ነው።"),
