    (15, 29, "ይሀም የእስራኤልን ልጆች ከኃጢአታቸው ያነጻቸው ዘንድ ጸዘለዓለም ሥርዓት ይሁናችሁ ፡ እግአብሔር ሙ ሴን እንዳዛዛው በዓመት አንድ ጊዜ ያድርገው።"),
