    (16, 3, "es ጣዖቱን ተክትለው (አምልከው) የሚሰስታበች መ ዋፅቻቸውን በከንቱ አይሠው ፡ በለ ዘመናችሁም እንዲህ ) ሥርናት ይሁናችሁ »።"),
