    (16, 5, "ከክስ ራኤል ልጆች ወኘን ወይም ክናንተ ሄንድ ከሚ ኖሩት ክደተኞኛችቕ አንዱም ይንዱ ስው ከዪሙጮ ቬበላ።"),
